// Synthetic archive generated by Apple's Foundation, independent of the Python decoder.
// Run on macOS: swift generate-kindle-metadata.swift /chosen/new/fixture.plist
import Foundation

@objc(SyncMetadataAttributes)
final class SyncMetadataAttributes: NSObject, NSSecureCoding {
    static var supportsSecureCoding: Bool { true }
    let attributes: NSDictionary
    init(_ attributes: NSDictionary) { self.attributes = attributes }
    required init?(coder: NSCoder) { fatalError("Fixture generator never decodes archives") }
    func encode(with coder: NSCoder) { coder.encode(attributes, forKey: "attributes") }
}

let metadata = SyncMetadataAttributes([
    "ASIN": "B012345678",
    "authors": ["author": ["Synthetic Writer", "Écrivain 二"]],
    "title": "Synthetic catalog title",
    "purchase_date": "synthetic-do-not-import",
    "content_size": NSNumber(value: 1234),
    "unused_data": Data([1, 2, 3])
])
let archive = try NSKeyedArchiver.archivedData(withRootObject: metadata, requiringSecureCoding: true)
try archive.write(to: URL(fileURLWithPath: CommandLine.arguments[1]), options: .withoutOverwriting)
